      "titel": "OWASP Top 10 for Agentic Applications",
      "dokument_version": "2026",
      "quelle": "https://genai.owasp.org/resources/",
      "muster": "Agentic Applications[^<]{0,40}?(20[0-9]{2})"
    },
    "state-of-agentic-ai-security-and-governance-v2-01": {
      "titel": "State of Agentic AI Security and Governance",
      "dokument_version": "2.01",
      "quelle": "https://genai.owasp.org/resources/",
      "muster": "Agentic AI Security and Governance[^0-9<]{0,20}([0-9]+\\.[0-9]+)"
    },
    "nist-cswp-29": {
      "titel": "NIST Cybersecurity Framework (CSWP 29)",
      "dokument_version": "2.0",
      "quelle": "https://www.nist.gov/cyberframework",
      "muster": "CSF ([0-9]+\\.[0-9]+)"
    },
    "nist-sp-800-218": {
      "titel": "NIST SP 800-218 Secure Software Development Framework",
      "dokument_version": "1.1",
      "quelle": "https://csrc.nist.gov/pubs/sp/800/218/final",
      "muster": "Version ([0-9]+\\.[0-9]+)",
      "anmerkung": "SP 800-218A (Generative AI) ist eine eigene Publikation, keine neuere Fassung von 800-218."
    },
    "celex-32016r0679-de-txt": {
      "titel": "DSGVO (Verordnung (EU) 2016/679)",
      "dokument_version": "konsolidiert 2016-05-04",
      "quelle": "https://eur-lex.europa.eu/legal-content/DE/TXT/?uri=CELEX:32016R0679",
      "anmerkung": "Amtsblattfassung; konsolidierte Staende ueber EUR-Lex pruefen.",
      "dokument_muster": "(04\\.05\\.2016|4\\.5\\.2016)"
    },
    "celex-32022l2555-de-txt": {
      "titel": "NIS2-Richtlinie (EU) 2022/2555",
      "dokument_version": "2022-12-14",
      "quelle": "https://eur-lex.europa.eu/legal-content/DE/TXT/?uri=CELEX:32022L2555",
      "dokument_muster": "(27\\.12\\.2022)",
      "anmerkung": "Amtsblattfassung. EUR-Lex fuehrt konsolidierte Fassungen ohne Versionsnummer — spaetere Aenderungen sind ueber die Fundstelle zu pruefen."
    },
    "celex-32022r2554-de-txt": {
