    "it-grundschutz-kompendium-edition2023": {
      "titel": "BSI IT-Grundschutz-Kompendium",
      "dokument_version": "Edition 2023",
      "quelle": "https://www.bsi.bund.de/DE/Themen/Unternehmen-und-Organisationen/Standards-und-Zertifizierung/IT-Grundschutz/IT-Grundschutz-Kompendium/it-grundschutz-kompendium_node.html",
      "muster": "Edition (20[0-9]{2})"
    },
    "cis-controls-version-8-1-2-march-2025": {
      "titel": "CIS Critical Security Controls",
      "dokument_version": "8.1",
      "quelle": "https://www.cisecurity.org/controls",
      "muster": "Controls v([0-9]+\\.[0-9]+)"
    },
    "iso-iec-27001-2022": {
      "titel": "ISO/IEC 27001",
      "dokument_version": "2022",
      "quelle": "https://www.iso.org/standard/27001",
      "anmerkung": "Fassung aus dem lizenzierten Dokument gelesen. Der ISO-Katalog ist kostenpflichtig und maschinell nicht verlaesslich auslesbar — ob inzwischen ein Amendment oder eine neue Ausgabe erschienen ist, bleibt manuell zu pruefen.",
      "dokument_muster": "(ISO/IEC 27001:[0-9]{4}|Third edition [0-9]{4}-[0-9]{2})"
    },
    "iso-42001": {
      "titel": "ISO/IEC 42001",
      "dokument_version": "2023",
      "quelle": "https://www.iso.org/standard/81230.html",
      "anmerkung": "Wie ISO 27001: Fassung aus dem Dokument belegt, Neuerscheinungen manuell pruefen.",
      "dokument_muster": "(ISO/IEC 42001:[0-9]{4}|First edition [0-9]{4}-[0-9]{2})"
    },
    "isa6-de-6-0-2": {
      "titel": "VDA ISA (TISAX)",
      "dokument_version": "6.0.2",
      "quelle": "https://portal.enx.com/de-DE/TISAX/downloads/",
      "anmerkung": "Fassung aus der lizenzierten Arbeitsmappe gelesen. Das ENX-Portal verlangt eine Anmeldung; neuere ISA-Releases sind dort manuell zu pruefen. GELTEND fuer Assessments bis 31.12.2026. Nachfolger ist VDA ISA 2027 (veroeffentlicht 01.07.2026), der fuer Assessments ab 01.01.2027 gilt und als tisax-isa2027-en im Bestand liegt — bis dahin ist 6.0.2 die massgebliche Fassung, ISA 2027 also kein Grund, diese als veraltet zu behandeln.",
      "dokument_muster": "(6\\.0\\.[0-9])"
    },
    "version-und-lizenz": {
      "titel": "BSI Kriterienkatalog C5 (maschinenlesbarer Katalog)",
      "dokument_version": "1.1.0",
      "quelle": "https://www.bsi.bund.de/dok/c5",
      "dokument_muster": "version: '([0-9]+\\.[0-9]+\\.[0-9]+)'"
    },
    "tisax-isa2027-en": {
      "titel": "VDA ISA 2027 (TISAX, Nachfolgefassung)",
      "dokument_version": "2027",
      "quelle": "https://portal.enx.com/de-DE/TISAX/downloads/",
      "anmerkung": "Veroeffentlicht 01.07.2026, GILT ERST fuer Assessments ab 01.01.2027. Der VDA ist auf jahresbasierte Versionsnamen gewechselt (kein ISA 7.0). Gegen 6.0.2: Kriterium 6.1.3 neu, 1.2.4 entfallen, Prototypenschutz vollstaendig neu strukturiert. Bis zum Stichtag NICHT als geltende Anforderung zitieren — dafuer gilt ISA 6.0.2.",
      "dokument_muster": "Version:\\s*(2027)"
    },
    "tisax-teilnehmerhandbuch": {
      "titel": "TISAX-Teilnehmerhandbuch (ENX)",
      "dokument_version": "2.8",
      "quelle": "https://portal.enx.com/de-de/TISAX/downloads/",
      "anmerkung": "Aufgenommen ist Fassung 2.8 vom 13.03.2025, ENX doc ID 602-DE, Klassifizierung 'Oeffentlich'. Die Fundstelle liegt hinter der Netzsperre dieser Umgebung (enx.com und portal.enx.com sind vom Egress-Proxy blockiert), die geltende Fassung ist von hier aus also NICHT pruefbar. Achtung: der VDA hat am 01.07.2026 die ISA2027 veroeffentlicht; eine daran angepasste Handbuchfassung ist wahrscheinlich. Vor Verwendung als geltender Stand manuell im ENX-Portal abgleichen.",
      "muster": "Version\\s*([0-9]+\\.[0-9]+)",
      "dokument_muster": "ENX doc ID[\\s\\S]{0,200}?\\n([0-9]+\\.[0-9]+)\\n"
    },
    "owasp-testing-guide-v4": {
      "titel": "OWASP Testing Guide (Vorgaenger des WSTG)",
      "dokument_version": "4.0",
      "quelle": "https://owasp.org/www-project-web-security-testing-guide/",
      "muster": "\\[Version ([0-9]+\\.[0-9]+)\\]",
      "anmerkung": "Projekt wurde in Web Security Testing Guide umbenannt; v4.0 ist der alte Testing Guide."
    },
    "bsig-gesetz-u-ber-das-bundesamt-fu-r-sicherheit-in-der-informationstechnik-und": {
      "titel": "BSIG — Gesetz ueber das Bundesamt fuer Sicherheit in der Informationstechnik",
      "dokument_version": "Ausfertigung 02.12.2025 (Fassung vor der Aenderung vom 11.03.2026)",
      "quelle": "https://www.gesetze-im-internet.de/bsig_2025/",
      "anmerkung": "VERALTET. Der Fundstellen-Resolver hat den Extrakt gegen das amtliche XML (BJNR12D0B0025.xml, Stand: geaendert durch Art. 4 G v. 11.3.2026 I Nr. 66) gehalten: 57 von 68 Paragrafen stimmen woertlich ueberein, 8 Woerter kommen im PDF gar nicht vor. Betroffen sind § 33 (Registrierungspflicht, jetzt ueber § 8 KRITIS-Dachgesetz) und Anlage 1. Die neuere Fassung liegt bereits als XML im Bestand; das PDF wird als Historiendokument gefuehrt (mappings/historie.json, Nachfolger bjnr12d0b0025). Kein Muster hinterlegt: gesetze-im-internet.de ist aus dieser Umgebung nicht erreichbar, der Stand wird deshalb manuell geprueft."
    },
    "bjnr12d0b0025": {
      "titel": "BSIG 2025 — amtliches XML (gesetze-im-internet.de)",
      "dokument_version": "Stand 11.03.2026 (Art. 4 G v. 11.3.2026 I Nr. 66)",
      "quelle": "https://www.gesetze-im-internet.de/bsig_2025/xml.zip",
      "anmerkung": "Primaertext, aus dem fixtures/ground-truth/bsig.json erzeugt wird."
    },
    "bjnr095800016": {
      "titel": "BSI-KritisV — Verordnung zur Bestimmung kritischer Anlagen",
